from collections import defaultdict, deque

def can_chain(dominoes):
    # Return an ordered list of dominoes forming a closed chain if possible,
    # otherwise return None. For empty input return empty list.
    if not dominoes:
        return []

    m = len(dominoes)
    adj = defaultdict(list)   # vertex -> list of (neighbor, edge_id)
    neighbors = defaultdict(set)
    for i, (a, b) in enumerate(dominoes):
        adj[a].append((b, i))
        adj[b].append((a, i))
        neighbors[a].add(b)
        neighbors[b].add(a)

    # degree check: all vertices with edges must have even degree
    for v in adj:
        if len(adj[v]) % 2 != 0:
            return None

    # connectivity check among vertices with degree > 0
    start = next((v for v in adj if adj[v]), None)
    if start is None:
        return []  # no edges
    visited = set()
    stack = [start]
    while stack:
        v = stack.pop()
        if v in visited:
            continue
        visited.add(v)
        for nb in neighbors[v]:
            if nb not in visited:
                stack.append(nb)
    for v in adj:
        if adj[v] and v not in visited:
            return None

    # Hierholzer's algorithm to find Eulerian circuit
    used = [False] * m
    # Copy adjacency lists because we'll modify them
    adj_copy = {v: list(lst) for v, lst in adj.items()}

    vertex_stack = [start]
    edge_stack = []  # stack of (edge_id, from_vertex, to_vertex) for traversed edges
    circuit_edges = []

    while vertex_stack:
        v = vertex_stack[-1]
        # skip used edges
        while adj_copy[v] and used[adj_copy[v][-1][1]]:
            adj_copy[v].pop()
        if adj_copy[v]:
            u, eid = adj_copy[v].pop()
            if used[eid]:
                continue
            used[eid] = True
            vertex_stack.append(u)
            edge_stack.append((eid, v, u))
        else:
            vertex_stack.pop()
            if edge_stack:
                eid, frm, to = edge_stack.pop()
                circuit_edges.append((eid, frm, to))

    if len(circuit_edges) != m:
        return None

    # circuit_edges is in reverse traversal order; reverse to get forward chain
    circuit_edges.reverse()

    # Map to oriented domino tuples
    result = []
    for eid, frm, to in circuit_edges:
        a, b = dominoes[eid]
        # orientation should match frm->to
        if (a, b) == (frm, to):
            result.append((a, b))
        elif (b, a) == (frm, to):
            result.append((b, a))
        else:
            # This can happen for loops where a == b, just append as-is
            result.append((a, b))

    return result
